**Polymorphism Example with AJAX Requests and ES6 Classes

### Summary
1. Define class with generic **makeRequest** to encapsulate baseline functionality.
2. Derive subclass with overridden **makeRequest** providing AJAX-specific behaviors, reflecting poly-variety or multiple behaviors.

### Implementation Code
```javascript
// Base class with a generic method that performs an AJAX request
class RequestHandlingBase {
  // Base method to simulate or perform asynchronous calls with delay
  makeRequest(url, options = {}) {
    console.log(`Base Method: Handling generic request to ${url}`);
    //Return simulated/true AJAX behavior
    return new Promise(resolve => {
      setTimeout(() => resolve(`Generic response from ${url}`), 1000);
    });
  }
}

// Subclass that overrides the makeRequest method to handle AJAX requests
class AjaxHandler extends RequestHandlingBase {
  // Overridden method to perform actual browser XMLHttpRequest
  makeRequest({ url, method = 'GET', data } = {}) {
    console.log(`AJAX call: Making ${method} request to ${url}`);
    return new Promise((resolve, reject) => {
      const xhttp = new XMLHttpRequest();
      xhttp.open(method, url, true);
      xhttp.setRequestHeader('Content-Type', 'application/json');
      xhttp.onreadystatechange = function () {
        if (this.readyState === 4) {
          if (this.status === 200) {
            console.log(`AJAX response: ${this.responseText}`)
            resolve(this.responseText);
          } else {
            console.error(`AJAX Error: HTTP status ${this.status}`); 
            reject(new Error(`${this.status} ${this.statusText}`));
          }
        }
      };
      // Send POST/PUT requests with JSON payload
      if (method.toUpperCase() === 'POST') {
        xhttp.send(JSON.stringify(data || null));
      } else {
        xhttp.send();
      }
    };
  }
}

// Example usage 
const basic = new RequestHandlingBase();
const advanced = new AjaxHandler();

// 4. Demonstrate with usage examples (showcase polymorphism)
/basic.makeRequest('/api/example.com?param1=val1,param').then( 
  result => console.log('Generic response: ' + result)
);

