// Base class representing basic animal behavior
class Animal {
public:
    // Constructor
    Animal(string name) : name(name) {};

    // Copy constructor (Deep Copy for strings is implicit here, but can be explicitly written)
    Animal(const Animal& other) { this->name = other.name; }

    // Destructor
    ~Animal() { cout << "Animal " << name << " is being destroyed.\n" << endl; }

    // Public method (Can be overridden)
    virtual void sound() {
        cout << "I am an animal, not specific type." << endl;
    }

    // Public member (shared across classes)
    string name;
};

// Derived class for weapons with virtual inheritance (Multiple Inheritance example)
class Weapon {
public:
    Weapon(string typeName) : typeName(typeName) { cout << "Weapon is created with type: " << typeName << "\n" << endl; }

    virtual ~Weapon() { cout << "Weapon is destroyed.\n" << endl; }

    virtual void weaponType() { cout << "Generic Weapon Type." << endl; }

    string typeName;
};

class Shield {
public:
    Shield(string typeName) : typeName(typeName) { cout << "Shield is created with type: " << typeName << "\n" << endl; }

    virtual ~Shield() { cout << "Shield is destroyed.\n" << endl; }

    virtual void shieldType() { cout << "Generic Shield Type." << endl; }

    string typeName;
};

// Derived animal classes with specific sound behavior
class Dog : virtual public Animal {
protected:
    void sound() override {
        Animal::sound(); 
        cout << "Dog has a different sound. Woof!\n" << endl;
    }
};

class Cat : public Animal {
protected:
    void sound() override {
        Animal::sound();
        cout << "Cat has a different sound. Meow!\n" << endl;
    }
};

// Dog object that contains weapons (Aggregation)
class ArmedDog : public Dog {
private:
    Weapon weapon;
    double strength;
    bool hasShield;
protected:
    string type;
public:
    // Aggregating weapons with Dog
    ArmedDog(string name, string weapon_type, double strength, bool hasShield) : Dog(name) {
        weapon.setType(weapon_type);
        this->strength = strength;
        this->hasShield = hasShield;
    }

    void applyWeapon() {
        weapon.use();
    }

// Function overloading
    void type() { cout << "Armed dog using: type.\n" << endl; }

// Function overriding
    void addArmor(bool has Shield) { cout << "Applied shield. Strength increased." << strength << "\n" << endl; }

